namespace ghidra.feature.vt.gui.provider.markuptable;





using docking.widgets.checkbox;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.filters;
using ghidra.feature.vt.gui.filters;

public class MarkupStatusFilter : CheckBoxBasedAncillaryFilter<VTMarkupItem> {

	public MarkupStatusFilter() : base("Markup Status")
    {
	}

	/* @Override */
	protected void createCheckBoxInfos() {
		ItemListener listener = e => fireStatusChanged(getFilterStatus());

		VTMarkupItemStatus[] values = VTMarkupItemStatus.values();
		foreach (VTMarkupItemStatus status in values) {
			GCheckBox checkBox = new GCheckBox(status.getDescription());
			checkBox.setSelected(true);
			checkBox.addItemListener(listener);
			CheckBoxInfo<VTMarkupItem> info = new MatchStatusCheckBoxInfo(checkBox, status);
			checkBoxInfos.add(info);
		}
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class MatchStatusCheckBoxInfo : CheckBoxInfo<VTMarkupItem> {

		private VTMarkupItemStatus status;

		public MatchStatusCheckBoxInfo(JCheckBox checkBox, VTMarkupItemStatus status) : base(checkBox)
    {
			this.status = status;
		}

		/* @Override */
		public bool matchesStatus(VTMarkupItem adapter) {
			if (!isSelected()) {
				return false;
			}
			return adapter.getStatus().equals(status);
		}
	}
}
